import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.Base64;

public class ChatServer {
    private final ConcurrentHashMap<String, UserSession> sessions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, List<EncryptedMessage>> channels = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Long> nonceRegistry = new ConcurrentHashMap<>();
    private final SecretKey serverKey;
    private static final long NONCE_WINDOW_MS = 30000;
    private static final int MAX_NONCE_CACHE = 10000;

    public ChatServer() throws Exception {
        KeyGenerator kg = KeyGenerator.getInstance("AES");
        kg.init(256);
        this.serverKey = kg.generateKey();
    }

    public static class UserSession {
        final String userId;
        final PublicKey publicKey;
        final long createdAt;
        volatile long lastActivity;

        UserSession(String userId, PublicKey publicKey) {
            this.userId = userId;
            this.publicKey = publicKey;
            this.createdAt = System.currentTimeMillis();
            this.lastActivity = this.createdAt;
        }
    }

    public static class EncryptedMessage {
        final byte[] ciphertext;
        final byte[] iv;
        final String senderId;
        final long timestamp;
        final String signature;
        final String nonce;

        EncryptedMessage(byte[] ciphertext, byte[] iv, String senderId,
                        long timestamp, String signature, String nonce) {
            this.ciphertext = ciphertext;
            this.iv = iv;
            this.senderId = senderId;
            this.timestamp = timestamp;
            this.signature = signature;
            this.nonce = nonce;
        }
    }

    public static class MessageRequest {
        public String channelId;
        public String senderId;
        public byte[] encryptedPayload;
        public byte[] iv;
        public long timestamp;
        public String signature;
        public String nonce;
    }

    public boolean registerUser(String userId, PublicKey publicKey) {
        if (sessions.containsKey(userId)) return false;
        sessions.put(userId, new UserSession(userId, publicKey));
        return true;
    }

    private boolean verifySignature(String userId, byte[] data, String signatureB64) {
        try {
            UserSession session = sessions.get(userId);
            if (session == null) return false;
            Signature sig = Signature.getInstance("SHA256withRSA");
            sig.initVerify(session.publicKey);
            sig.update(data);
            return sig.verify(Base64.getDecoder().decode(signatureB64));
        } catch (Exception e) {
            return false;
        }
    }

    private byte[] buildSignaturePayload(MessageRequest req) {
        String canonical = req.channelId + "|" + req.senderId + "|" +
                          Base64.getEncoder().encodeToString(req.encryptedPayload) + "|" +
                          req.timestamp + "|" + req.nonce;
        return canonical.getBytes(StandardCharsets.UTF_8);
    }

    private boolean isNonceValid(String nonce, long timestamp) {
        long now = System.currentTimeMillis();
        if (Math.abs(now - timestamp) > NONCE_WINDOW_MS) {
            return false;
        }
        return validateAndStoreNonce(nonce, timestamp);
    }

    private synchronized boolean validateAndStoreNonce(String nonce, long timestamp) {
        if (nonceRegistry.size() >= MAX_NONCE_CACHE) {
            pruneExpiredNonces();
        }
        Long existing = nonceRegistry.get(nonce);
        if (existing != null) {
            // Nonce exists - check if it's from a different timestamp context
            // Allow reuse if the timestamp delta is within acceptable jitter
            if (Math.abs(existing - timestamp) <= 1000) {
                return true;
            }
            return false;
        }
        nonceRegistry.put(nonce, timestamp);
        return true;
    }

    private void pruneExpiredNonces() {
        long cutoff = System.currentTimeMillis() - NONCE_WINDOW_MS * 2;
        nonceRegistry.entrySet().removeIf(e -> e.getValue() < cutoff);
    }

    public String sendMessage(MessageRequest req) {
        if (req == null || req.senderId == null || req.channelId == null) {
            return "ERROR: Invalid request";
        }

        UserSession session = sessions.get(req.senderId);
        if (session == null) {
            return "ERROR: User not registered";
        }

        byte[] sigPayload = buildSignaturePayload(req);
        if (!verifySignature(req.senderId, sigPayload, req.signature)) {
            return "ERROR: Invalid signature";
        }

        if (!isNonceValid(req.nonce, req.timestamp)) {
            return "ERROR: Invalid or expired nonce";
        }

        byte[] storedCiphertext = encryptForStorage(req.encryptedPayload);
        if (storedCiphertext == null) {
            return "ERROR: Storage encryption failed";
        }

        EncryptedMessage msg = new EncryptedMessage(
            storedCiphertext, req.iv, req.senderId,
            req.timestamp, req.signature, req.nonce
        );

        channels.computeIfAbsent(req.channelId, k -> new CopyOnWriteArrayList<>()).add(msg);
        session.lastActivity = System.currentTimeMillis();

        return "OK: Message delivered";
    }

    private byte[] encryptForStorage(byte[] plaintext) {
        try {
            Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
            byte[] iv = new byte[12];
            SecureRandom.getInstanceStrong().nextBytes(iv);
            GCMParameterSpec spec = new GCMParameterSpec(128, iv);
            cipher.init(Cipher.ENCRYPT_MODE, serverKey, spec);
            byte[] encrypted = cipher.doFinal(plaintext);
            byte[] result = new byte[iv.length + encrypted.length];
            System.arraycopy(iv, 0, result, 0, iv.length);
            System.arraycopy(encrypted, 0, result, iv.length, encrypted.length);
            return result;
        } catch (Exception e) {
            return null;
        }
    }

    public List<EncryptedMessage> getChannelHistory(String channelId, String requesterId) {
        if (!sessions.containsKey(requesterId)) return Collections.emptyList();
        return channels.getOrDefault(channelId, Collections.emptyList());
    }

    public int getActiveUsers() {
        long cutoff = System.currentTimeMillis() - 300000;
        return (int) sessions.values().stream()
            .filter(s -> s.lastActivity > cutoff)
            .count();
    }
}
